#!/usr/bin/env python3
"""Парсер btsnoop_hci.log: извлекает ATT (BLE GATT) и RFCOMM (SPP) payload и ищет кадры протокола 1MORE/JieLi.

Использование:
    python3 tools/btsnoop.py captures/btsnoop_hci.log -o captures/report.md   # -o — только с одним файлом
    python3 tools/btsnoop.py captures/*.log --raw                              # отчёты в stdout

Только stdlib, Python 3.10+. Тесты: python3 tests/test_btsnoop.py
"""

import argparse
import operator
import struct
import sys
from collections import Counter
from dataclasses import dataclass, field
from datetime import datetime, timezone
from functools import reduce
from pathlib import Path

MAGIC = b"btsnoop\0"
DLT_H4 = 1002

H4_ACL = 0x02
H4_EVT = 0x04

EVT_LE_META = 0x3E
LE_ADV_LEGACY = 0x01
LE_ADV_EXTENDED = 0x02

L2CAP_SDP = 0x0001
L2CAP_ATT = 0x0004
L2CAP_RFCOMM_MIN = 0x0040

ATT_READ_BY_TYPE_RESP = 0x09
ATT_WRITE_REQ = 0x12
ATT_READ_BY_GROUP_RESP = 0x11
ATT_NOTIFY = 0x1B
ATT_INDICATE = 0x1D
ATT_WRITE_CMD = 0x52

RFCOMM_CONTROLS = {0x0F, 0x1F, 0x2F, 0x3F, 0x43, 0x53, 0x63, 0x73, 0xEF, 0xFF}

AD_TYPES_NAMES = {0x08, 0x09}
AD_TYPES_UUID16 = {0x02, 0x03}
AD_TYPES_UUID128 = {0x06, 0x07}

FRAME_DIR = (0x11, 0x01)
FRAME_PREFIX = (0x01, 0x00)
FRAME_MIN_LEN = 9
FRAME_MAX_PAYLOAD = 512

UUID16_BASE = "0000-1000-8000-00805f9b34fb"

CMD_DEVICE_INFO = 0x36
CMD_BATTERY_INFO = 0x37
CMD_DELETE_MUSIC = 0x49
CMD_HANDSHAKE = 0x4D
CMD_BT_STATUS = 0x4E
CMD_EQ_SET_BAND = 0x53
CMD_EQ_BANDS = 0x54
CMD_ANC_SET = 0x5E
CMD_ANC_GET = 0x5F
CMD_AWARENESS_SET = 0x60
CMD_AWARENESS_GET = 0x61
CMD_EQ_SET = 0x69
CMD_EQ_GET = 0x6A
CMD_LINK_SET = 0x6B
CMD_LINK_GET = 0x6C
CMD_FW_UPDATE = (0x71, 0x72, 0x73)

CMD_NAMES = {
    CMD_DEVICE_INFO: "query device info",
    CMD_BATTERY_INFO: "query battery info",
    CMD_DELETE_MUSIC: "DELETE MUSIC (никогда не слать)",
    CMD_HANDSHAKE: "handshake",
    CMD_BT_STATUS: "battery / bt status",
    CMD_EQ_SET_BAND: "set EQ band",
    CMD_EQ_BANDS: "EQ band table",
    CMD_ANC_SET: "set listening mode (ANC)",
    CMD_ANC_GET: "get listening mode (ANC)",
    CMD_AWARENESS_SET: "set total awareness",
    CMD_AWARENESS_GET: "get total awareness",
    CMD_EQ_SET: "set sound preset (EQ)",
    CMD_EQ_GET: "get sound preset (EQ)",
    CMD_LINK_SET: "set game/link mode",
    CMD_LINK_GET: "get game/link mode",
    **dict.fromkeys(CMD_FW_UPDATE, "FW UPDATE (опасно)"),
}

ANC_MODES = {
    0: "выкл",
    1: "сильный ANC",
    2: "слабый ANC",
    3: "прозрачность",
    4: "анти-ветер",
    5: "пропускание голоса",
    6: "усиление голоса",
    7: "адаптивный",
}

LINK_MODES = {0: "стандарт", 1: "низкая задержка", 2: "LDAC"}

TS_0AD_TO_1970_US = 62135596800000000


def xor(data: bytes) -> int:
    return reduce(operator.xor, data, 0)



@dataclass
class OneMoreFrame:
    direction_byte: int
    cmd: int
    length: int
    seq: int
    checksum_byte: int
    checksum_ok: bool | None
    variant: str
    payload: bytes

    @property
    def total_len(self) -> int:
        return 9 + self.length


def parse_onemore(data: bytes) -> OneMoreFrame | None:
    if len(data) < FRAME_MIN_LEN:
        return None
    if data[0] not in FRAME_DIR or tuple(data[1:3]) != FRAME_PREFIX:
        return None
    if (data[6], data[7]) == (0x00, 0x01):
        variant = "BE"
        length = struct.unpack(">H", data[4:6])[0]
        seq = struct.unpack(">H", data[6:8])[0]
        checksum_ok = xor(data[:8]) == data[8]
    elif (data[6], data[7]) == (0x01, 0x00):
        variant = "LE"
        length = struct.unpack("<H", data[4:6])[0]
        seq = struct.unpack("<H", data[6:8])[0]
        checksum_ok = None
    else:
        return None
    if length > FRAME_MAX_PAYLOAD:
        return None
    return OneMoreFrame(data[0], data[3], length, seq, data[8], checksum_ok, variant, data[9 : 9 + length])


def extract_onemore(data: bytes) -> list[tuple[int, OneMoreFrame]]:
    found = []
    pos = 0
    while pos + FRAME_MIN_LEN <= len(data):
        frame = parse_onemore(data[pos:])
        if frame is None:
            pos += 1
            continue
        found.append((pos, frame))
        pos += frame.total_len
    return found


def fmt_uuid(raw: bytes) -> str:
    if len(raw) == 2:
        return f"0x{raw.hex()}"
    if len(raw) == 16:
        s = raw[::-1].hex()
        u = f"{s[:8]}-{s[8:12]}-{s[12:16]}-{s[16:20]}-{s[20:]}"
        if u[9:] == UUID16_BASE:
            return f"0x{u[:4]}"
        return u
    return raw.hex()


@dataclass(slots=True)
class GattMap:
    services: list[tuple[int, int, str]] = field(default_factory=list)
    chars: dict[int, str] = field(default_factory=dict)

    def add_service(self, start: int, end: int, uuid: str) -> None:
        self.services.append((start, end, uuid))

    def add_char_decl(self, value: int, uuid: str) -> None:
        self.chars[value] = uuid

    def uuid(self, handle: int) -> str:
        return self.chars.get(handle, "")


@dataclass(slots=True)
class AdvInfo:
    names: set[str] = field(default_factory=set)
    uuids: set[str] = field(default_factory=set)


@dataclass(slots=True)
class Record:
    ts: int
    tx: bool
    data: bytes


@dataclass(slots=True)
class Event:
    ts: int
    direction: str
    transport: str
    handle: int | None
    payload: bytes
    frames: list[OneMoreFrame] = field(default_factory=list)


def read_btsnoop(path: str | Path):
    blob = Path(path).read_bytes()
    if blob[:8] != MAGIC:
        raise ValueError(f"{path}: нет сигнатуры btsnoop")
    pos = 16
    while pos + 24 <= len(blob):
        _orig, inc, flags, _drops = struct.unpack(">IIII", blob[pos : pos + 16])
        (ts,) = struct.unpack(">q", blob[pos + 16 : pos + 24])
        pos += 24
        data = blob[pos : pos + inc]
        pos += inc
        yield Record(ts, (flags & 1) == 0, data)


class Analyzer:
    def __init__(self) -> None:
        self.gatt = GattMap()
        self.events: list[Event] = []
        self.adv: dict[str, AdvInfo] = {}
        self.cmd_stats: Counter = Counter()
        self.acl_count = 0
        self.evt_count = 0
        self.sdp_count = 0
        self.skipped_fragments = 0
        self.checksum_bad = 0

    def feed(self, rec: Record) -> None:
        data = rec.data
        if not data:
            return
        if data[0] == H4_ACL:
            self.acl_count += 1
            self.parse_acl(rec, data[1:])
        elif data[0] == H4_EVT:
            self.evt_count += 1
            self.parse_evt(data[1:])

    def parse_acl(self, rec: Record, p: bytes) -> None:
        if len(p) < 5:
            return
        hb, dlen = struct.unpack("<HH", p[:4])
        if ((hb >> 12) & 0b11) == 0b01:
            self.skipped_fragments += 1
            return
        l2 = p[4 : 4 + dlen]
        if len(l2) < 4:
            return
        l2len, cid = struct.unpack("<HH", l2[:4])
        body = l2[4 : 4 + l2len]
        if cid == L2CAP_ATT:
            self.parse_att(rec, body)
        elif cid == L2CAP_SDP:
            self.sdp_count += 1
        elif cid >= L2CAP_RFCOMM_MIN:
            self.parse_rfcomm(rec, body)

    def parse_att(self, rec: Record, body: bytes) -> None:
        if not body:
            return
        op = body[0]
        if op in (ATT_WRITE_CMD, ATT_WRITE_REQ):
            if len(body) >= 3:
                (handle,) = struct.unpack("<H", body[1:3])
                self.emit(rec, "ATT write", handle, body[3:])
        elif op in (ATT_NOTIFY, ATT_INDICATE):
            if len(body) >= 3:
                (handle,) = struct.unpack("<H", body[1:3])
                self.emit(rec, "ATT notify" if op == ATT_NOTIFY else "ATT indicate", handle, body[3:])
        elif op == ATT_READ_BY_GROUP_RESP:
            self.parse_services(body[1:])
        elif op == ATT_READ_BY_TYPE_RESP:
            self.parse_char_decls(body[1:])

    def parse_services(self, entries: bytes) -> None:
        for size in (20, 6):
            if entries and len(entries) % size == 0:
                for off in range(0, len(entries), size):
                    start, end = struct.unpack("<HH", entries[off : off + 4])
                    self.gatt.add_service(start, end, fmt_uuid(entries[off + 4 : off + size]))
                break

    def parse_char_decls(self, entries: bytes) -> None:
        for size in (21, 7):
            if entries and len(entries) % size == 0:
                for off in range(0, len(entries), size):
                    _decl, _props, value = struct.unpack("<HBH", entries[off : off + 5])
                    self.gatt.add_char_decl(value, fmt_uuid(entries[off + 5 : off + size]))
                break

    def parse_rfcomm(self, rec: Record, payload: bytes) -> None:
        if len(payload) < 4 or payload[0] & 1 == 0:
            return
        control = payload[1]
        if control not in RFCOMM_CONTROLS:
            return
        if payload[2] & 1:
            length = payload[2] >> 1
            dstart = 3
        else:
            if len(payload) < 5:
                return
            length = struct.unpack("<H", payload[2:4])[0] >> 1
            dstart = 4
        data = payload[dstart : dstart + length]
        self.emit(rec, "RFCOMM", None, data)

    def emit(self, rec: Record, transport: str, handle: int | None, value: bytes) -> None:
        frames = [f for _, f in extract_onemore(value)]
        direction = "TX" if rec.tx else "RX"
        for f in frames:
            self.cmd_stats[(direction, f.cmd)] += 1
            if f.checksum_ok is False:
                self.checksum_bad += 1
        self.events.append(Event(rec.ts, direction, transport, handle, value, frames))

    def parse_evt(self, p: bytes) -> None:
        if len(p) < 2:
            return
        code, plen = p[0], p[1]
        if code != EVT_LE_META:
            return
        body = p[2 : 2 + plen]
        if not body:
            return
        sub = body[0]
        if sub == LE_ADV_LEGACY:
            self.parse_adv_legacy(body[1:])
        elif sub == LE_ADV_EXTENDED:
            self.parse_adv_extended(body[1:])

    def parse_adv_legacy(self, body: bytes) -> None:
        if not body:
            return
        num = body[0]
        off = 1
        for _ in range(num):
            try:
                addr = body[off + 2 : off + 8].hex(":")
                dlen = body[off + 8]
                self.scan_ad(body[off + 9 : off + 9 + dlen], addr)
                off += 9 + dlen
            except IndexError:
                return

    def parse_adv_extended(self, body: bytes) -> None:
        if not body:
            return
        num = body[0]
        off = 1
        for _ in range(num):
            try:
                addr = body[off + 3 : off + 9].hex(":")
                dlen = body[off + 9]
                self.scan_ad(body[off + 10 : off + 10 + dlen], addr)
                off += 10 + dlen + 1
            except IndexError:
                return

    def scan_ad(self, data: bytes, addr: str) -> None:
        info = self.adv.setdefault(addr, AdvInfo())
        i = 0
        while i < len(data):
            ln = data[i]
            if ln == 0 or i + 1 + ln > len(data):
                break
            typ = data[i + 1]
            seg = data[i + 2 : i + 1 + ln]
            if typ in AD_TYPES_NAMES:
                name = seg.decode("utf-8", "replace").strip()
                if name:
                    info.names.add(name)
            elif typ in AD_TYPES_UUID16:
                for j in range(0, len(seg) - 1, 2):
                    info.uuids.add(fmt_uuid(seg[j : j + 2]))
            elif typ in AD_TYPES_UUID128:
                for j in range(0, len(seg) - 15, 16):
                    info.uuids.add(fmt_uuid(seg[j : j + 16]))
            i += ln + 1


def analyze(path: str | Path) -> Analyzer:
    an = Analyzer()
    for rec in read_btsnoop(path):
        an.feed(rec)
    return an


def fmt_time(ts: int) -> str:
    if ts > 10**17:
        ts -= TS_0AD_TO_1970_US
    try:
        return datetime.fromtimestamp(ts / 1_000_000, tz=timezone.utc).strftime("%H:%M:%S.%f")[:-3]
    except (OverflowError, OSError, ValueError):
        return str(ts)


def battery_of(f: OneMoreFrame) -> tuple[int, int, int] | None:
    """(left%, right%, case%) из ответа 0x4E, либо None."""
    p = f.payload
    if f.cmd != CMD_BT_STATUS or f.direction_byte != 0x01 or len(p) < 10:
        return None
    return p[4], p[8], p[9]


def decode_value(f: OneMoreFrame) -> str:
    p = f.payload
    if not p:
        return ""
    if f.cmd in (CMD_ANC_SET, CMD_ANC_GET) and len(p) == 1:
        return f" ({ANC_MODES.get(p[0], f'режим {p[0]}?')})"
    if f.cmd in (CMD_LINK_SET, CMD_LINK_GET) and len(p) == 1:
        return f" ({LINK_MODES.get(p[0], f'режим {p[0]}?')})"
    if f.cmd in (CMD_EQ_SET, CMD_EQ_GET) and len(p) == 1:
        return f" (пресет {p[0]})"
    battery = battery_of(f)
    if battery:
        left, right, case = battery
        return f" (L={left}% R={right}% кейс={case}%)"
    return ""


def describe_frame(f: OneMoreFrame) -> str:
    name = CMD_NAMES.get(f.cmd, "неизвестная")
    cs = {True: "OK", False: "BAD", None: "?"}[f.checksum_ok]
    arrow = "host->buds" if f.direction_byte == 0x11 else "buds->host"
    return (
        f"cmd=0x{f.cmd:02X} ({name}) {arrow} len={f.length} seq={f.seq} "
        f"crc={cs} variant={f.variant} payload={f.payload.hex()}{decode_value(f)}"
    )


def render_report(an: Analyzer, label: str, raw: bool = False) -> str:
    lines = [f"# Отчёт btsnoop: {label}", ""]
    total_frames = sum(an.cmd_stats.values())
    lines.append(
        f"- записей HCI: ACL={an.acl_count}, EVT={an.evt_count}, SDP={an.sdp_count}, "
        f"пропущено ACL-продолжений={an.skipped_fragments}"
    )
    lines.append(
        f"- ATT/RFCOMM событий: {len(an.events)}, кадров 1MORE: {total_frames}, "
        f"с плохой чексуммой: {an.checksum_bad}"
    )
    if an.adv:
        lines += ["", "## BLE-устройства в эфире"]
        for addr, info in sorted(an.adv.items()):
            names = ", ".join(sorted(info.names)) or "?"
            uuids = ", ".join(sorted(info.uuids)) or "-"
            lines.append(f"- {addr}: {names} [{uuids}]")
    if an.gatt.services or an.gatt.chars:
        lines += ["", "## GATT"]
        for start, end, uuid in an.gatt.services:
            lines.append(f"- сервис {uuid} (handles 0x{start:04X}-0x{end:04X})")
        for handle in sorted(an.gatt.chars):
            lines.append(f"- характеристика 0x{handle:04X} -> {an.gatt.chars[handle]}")
    if an.cmd_stats:
        lines += ["", "## Команды 1MORE", "", "| cmd | имя | TX | RX |", "|---|---|---|---|"]
        for c in sorted({cmd for _, cmd in an.cmd_stats}):
            name = CMD_NAMES.get(c, "неизвестная")
            tx = an.cmd_stats.get(("TX", c), 0)
            rx = an.cmd_stats.get(("RX", c), 0)
            lines.append(f"| 0x{c:02X} | {name} | {tx} | {rx} |")
    shown = an.events if raw else [e for e in an.events if e.frames]
    if shown:
        lines += ["", "## Все payload" if raw else "## Кадры 1MORE"]
        for e in shown:
            suffix = ""
            if e.handle is not None:
                cu = an.gatt.uuid(e.handle)
                suffix = f" -> {cu}" if cu else f" h=0x{e.handle:04X}"
            lines.append(f"- {fmt_time(e.ts)} {e.direction} {e.transport}{suffix}")
            if e.frames:
                for f in e.frames:
                    lines.append(f"  - {describe_frame(f)}")
            else:
                lines.append(f"  - payload: {e.payload.hex()}")
    if not an.cmd_stats:
        lines += [
            "",
            "Кадров 1MORE не найдено. Проверьте, что лог снят во время активной сессии",
            "официального приложения (подключение наушников + действия в интерфейсе).",
        ]
    return "\n".join(lines) + "\n"


def analyze_file(path: str | Path, raw: bool = False, out: str | Path | None = None) -> None:
    report = render_report(analyze(path), str(path), raw)
    if out:
        Path(out).write_text(report, encoding="utf-8")
        print(f"Отчёт: {out}")
    else:
        print(report, end="")


def main() -> None:
    ap = argparse.ArgumentParser(description="Извлекает кадры протокола 1MORE из btsnoop_hci.log")
    ap.add_argument("files", nargs="+", help="файлы btsnoop_hci.log")
    ap.add_argument("-o", "--out", help="файл отчёта (только для одного входного файла)")
    ap.add_argument("--raw", action="store_true", help="показывать все ATT/RFCOMM payload, не только кадры 1MORE")
    args = ap.parse_args()
    if args.out and len(args.files) > 1:
        ap.error("-o/--out можно использовать только с одним входным файлом")
    failed = False
    for f in args.files:
        try:
            analyze_file(f, args.raw, args.out)
        except (OSError, ValueError) as e:
            print(f"Ошибка: {e}", file=sys.stderr)
            failed = True
    if failed:
        sys.exit(1)


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""Парсер btsnoop_hci.log: извлекает ATT (BLE GATT) и RFCOMM (SPP) payload и ищет кадры протокола 1MORE/JieLi.

Использование:
    python3 tools/btsnoop.py captures/btsnoop_hci.log -o captures/report.md   # -o — только с одним файлом
    python3 tools/btsnoop.py captures/*.log --raw                              # отчёты в stdout

Только stdlib, Python 3.10+. Тесты: python3 tests/test_btsnoop.py
"""

import argparse
import operator
import struct
import sys
from collections import Counter
from dataclasses import dataclass, field
from datetime import datetime, timezone
from functools import reduce
from pathlib import Path

MAGIC = b"btsnoop\0"
DLT_H4 = 1002

H4_ACL = 0x02
H4_EVT = 0x04

EVT_LE_META = 0x3E
LE_ADV_LEGACY = 0x01
LE_ADV_EXTENDED = 0x02

L2CAP_SDP = 0x0001
L2CAP_ATT = 0x0004
L2CAP_RFCOMM_MIN = 0x0040

ATT_READ_BY_TYPE_RESP = 0x09
ATT_WRITE_REQ = 0x12
ATT_READ_BY_GROUP_RESP = 0x11
ATT_NOTIFY = 0x1B
ATT_INDICATE = 0x1D
ATT_WRITE_CMD = 0x52

RFCOMM_CONTROLS = {0x0F, 0x1F, 0x2F, 0x3F, 0x43, 0x53, 0x63, 0x73, 0xEF, 0xFF}

AD_TYPES_NAMES = {0x08, 0x09}
AD_TYPES_UUID16 = {0x02, 0x03}
AD_TYPES_UUID128 = {0x06, 0x07}

FRAME_DIR = (0x11, 0x01)
FRAME_PREFIX = (0x01, 0x00)
FRAME_MIN_LEN = 9
FRAME_MAX_PAYLOAD = 512

UUID16_BASE = "0000-1000-8000-00805f9b34fb"

CMD_DEVICE_INFO = 0x36
CMD_BATTERY_INFO = 0x37
CMD_DELETE_MUSIC = 0x49
CMD_HANDSHAKE = 0x4D
CMD_BT_STATUS = 0x4E
CMD_EQ_SET_BAND = 0x53
CMD_EQ_BANDS = 0x54
CMD_ANC_SET = 0x5E
CMD_ANC_GET = 0x5F
CMD_AWARENESS_SET = 0x60
CMD_AWARENESS_GET = 0x61
CMD_EQ_SET = 0x69
CMD_EQ_GET = 0x6A
CMD_LINK_SET = 0x6B
CMD_LINK_GET = 0x6C
CMD_FW_UPDATE = (0x71, 0x72, 0x73)

CMD_NAMES = {
    CMD_DEVICE_INFO: "query device info",
    CMD_BATTERY_INFO: "query battery info",
    CMD_DELETE_MUSIC: "DELETE MUSIC (никогда не слать)",
    CMD_HANDSHAKE: "handshake",
    CMD_BT_STATUS: "battery / bt status",
    CMD_EQ_SET_BAND: "set EQ band",
    CMD_EQ_BANDS: "EQ band table",
    CMD_ANC_SET: "set listening mode (ANC)",
    CMD_ANC_GET: "get listening mode (ANC)",
    CMD_AWARENESS_SET: "set total awareness",
    CMD_AWARENESS_GET: "get total awareness",
    CMD_EQ_SET: "set sound preset (EQ)",
    CMD_EQ_GET: "get sound preset (EQ)",
    CMD_LINK_SET: "set game/link mode",
    CMD_LINK_GET: "get game/link mode",
    **dict.fromkeys(CMD_FW_UPDATE, "FW UPDATE (опасно)"),
}

ANC_MODES = {
    0: "выкл",
    1: "сильный ANC",
    2: "слабый ANC",
    3: "прозрачность",
    4: "анти-ветер",
    5: "пропускание голоса",
    6: "усиление голоса",
    7: "адаптивный",
}

LINK_MODES = {0: "стандарт", 1: "низкая задержка", 2: "LDAC"}

TS_0AD_TO_1970_US = 62135596800000000


def xor(data: bytes) -> int:
    return reduce(operator.xor, data, 0)



@dataclass
class OneMoreFrame:
    direction_byte: int
    cmd: int
    length: int
    seq: int
    checksum_byte: int
    checksum_ok: bool | None
    variant: str
    payload: bytes

    @property
    def total_len(self) -> int:
        return 9 + self.length


def parse_onemore(data: bytes) -> OneMoreFrame | None:
    if len(data) < FRAME_MIN_LEN:
        return None
    if data[0] not in FRAME_DIR or tuple(data[1:3]) != FRAME_PREFIX:
        return None
    if (data[6], data[7]) == (0x00, 0x01):
        variant = "BE"
        length = struct.unpack(">H", data[4:6])[0]
        seq = struct.unpack(">H", data[6:8])[0]
        checksum_ok = xor(data[:8]) == data[8]
    elif (data[6], data[7]) == (0x01, 0x00):
        variant = "LE"
        length = struct.unpack("<H", data[4:6])[0]
        seq = struct.unpack("<H", data[6:8])[0]
        checksum_ok = None
    else:
        return None
    if length > FRAME_MAX_PAYLOAD:
        return None
    return OneMoreFrame(data[0], data[3], length, seq, data[8], checksum_ok, variant, data[9 : 9 + length])


def extract_onemore(data: bytes) -> list[tuple[int, OneMoreFrame]]:
    found = []
    pos = 0
    while pos + FRAME_MIN_LEN <= len(data):
        frame = parse_onemore(data[pos:])
        if frame is None:
            pos += 1
            continue
        found.append((pos, frame))
        pos += frame.total_len
    return found


def fmt_uuid(raw: bytes) -> str:
    if len(raw) == 2:
        return f"0x{raw.hex()}"
    if len(raw) == 16:
        s = raw[::-1].hex()
        u = f"{s[:8]}-{s[8:12]}-{s[12:16]}-{s[16:20]}-{s[20:]}"
        if u[9:] == UUID16_BASE:
            return f"0x{u[:4]}"
        return u
    return raw.hex()


@dataclass(slots=True)
class GattMap:
    services: list[tuple[int, int, str]] = field(default_factory=list)
    chars: dict[int, str] = field(default_factory=dict)

    def add_service(self, start: int, end: int, uuid: str) -> None:
        self.services.append((start, end, uuid))

    def add_char_decl(self, value: int, uuid: str) -> None:
        self.chars[value] = uuid

    def uuid(self, handle: int) -> str:
        return self.chars.get(handle, "")


@dataclass(slots=True)
class AdvInfo:
    names: set[str] = field(default_factory=set)
    uuids: set[str] = field(default_factory=set)


@dataclass(slots=True)
class Record:
    ts: int
    tx: bool
    data: bytes


@dataclass(slots=True)
class Event:
    ts: int
    direction: str
    transport: str
    handle: int | None
    payload: bytes
    frames: list[OneMoreFrame] = field(default_factory=list)


def read_btsnoop(path: str | Path):
    blob = Path(path).read_bytes()
    if blob[:8] != MAGIC:
        raise ValueError(f"{path}: нет сигнатуры btsnoop")
    pos = 16
    while pos + 24 <= len(blob):
        _orig, inc, flags, _drops = struct.unpack(">IIII", blob[pos : pos + 16])
        (ts,) = struct.unpack(">q", blob[pos + 16 : pos + 24])
        pos += 24
        data = blob[pos : pos + inc]
        pos += inc
        yield Record(ts, (flags & 1) == 0, data)


class Analyzer:
    def __init__(self) -> None:
        self.gatt = GattMap()
        self.events: list[Event] = []
        self.adv: dict[str, AdvInfo] = {}
        self.cmd_stats: Counter = Counter()
        self.acl_count = 0
        self.evt_count = 0
        self.sdp_count = 0
        self.skipped_fragments = 0
        self.checksum_bad = 0

    def feed(self, rec: Record) -> None:
        data = rec.data
        if not data:
            return
        if data[0] == H4_ACL:
            self.acl_count += 1
            self.parse_acl(rec, data[1:])
        elif data[0] == H4_EVT:
            self.evt_count += 1
            self.parse_evt(data[1:])

    def parse_acl(self, rec: Record, p: bytes) -> None:
        if len(p) < 5:
            return
        hb, dlen = struct.unpack("<HH", p[:4])
        if ((hb >> 12) & 0b11) == 0b01:
            self.skipped_fragments += 1
            return
        l2 = p[4 : 4 + dlen]
        if len(l2) < 4:
            return
        l2len, cid = struct.unpack("<HH", l2[:4])
        body = l2[4 : 4 + l2len]
        if cid == L2CAP_ATT:
            self.parse_att(rec, body)
        elif cid == L2CAP_SDP:
            self.sdp_count += 1
        elif cid >= L2CAP_RFCOMM_MIN:
            self.parse_rfcomm(rec, body)

    def parse_att(self, rec: Record, body: bytes) -> None:
        if not body:
            return
        op = body[0]
        if op in (ATT_WRITE_CMD, ATT_WRITE_REQ):
            if len(body) >= 3:
                (handle,) = struct.unpack("<H", body[1:3])
                self.emit(rec, "ATT write", handle, body[3:])
        elif op in (ATT_NOTIFY, ATT_INDICATE):
            if len(body) >= 3:
                (handle,) = struct.unpack("<H", body[1:3])
                self.emit(rec, "ATT notify" if op == ATT_NOTIFY else "ATT indicate", handle, body[3:])
        elif op == ATT_READ_BY_GROUP_RESP:
            self.parse_services(body[1:])
        elif op == ATT_READ_BY_TYPE_RESP:
            self.parse_char_decls(body[1:])

    def parse_services(self, entries: bytes) -> None:
        for size in (20, 6):
            if entries and len(entries) % size == 0:
                for off in range(0, len(entries), size):
                    start, end = struct.unpack("<HH", entries[off : off + 4])
                    self.gatt.add_service(start, end, fmt_uuid(entries[off + 4 : off + size]))
                break

    def parse_char_decls(self, entries: bytes) -> None:
        for size in (21, 7):
            if entries and len(entries) % size == 0:
                for off in range(0, len(entries), size):
                    _decl, _props, value = struct.unpack("<HBH", entries[off : off + 5])
                    self.gatt.add_char_decl(value, fmt_uuid(entries[off + 5 : off + size]))
                break

    def parse_rfcomm(self, rec: Record, payload: bytes) -> None:
        if len(payload) < 4 or payload[0] & 1 == 0:
            return
        control = payload[1]
        if control not in RFCOMM_CONTROLS:
            return
        if payload[2] & 1:
            length = payload[2] >> 1
            dstart = 3
        else:
            if len(payload) < 5:
                return
            length = struct.unpack("<H", payload[2:4])[0] >> 1
            dstart = 4
        data = payload[dstart : dstart + length]
        self.emit(rec, "RFCOMM", None, data)

    def emit(self, rec: Record, transport: str, handle: int | None, value: bytes) -> None:
        frames = [f for _, f in extract_onemore(value)]
        direction = "TX" if rec.tx else "RX"
        for f in frames:
            self.cmd_stats[(direction, f.cmd)] += 1
            if f.checksum_ok is False:
                self.checksum_bad += 1
        self.events.append(Event(rec.ts, direction, transport, handle, value, frames))

    def parse_evt(self, p: bytes) -> None:
        if len(p) < 2:
            return
        code, plen = p[0], p[1]
        if code != EVT_LE_META:
            return
        body = p[2 : 2 + plen]
        if not body:
            return
        sub = body[0]
        if sub == LE_ADV_LEGACY:
            self.parse_adv_legacy(body[1:])
        elif sub == LE_ADV_EXTENDED:
            self.parse_adv_extended(body[1:])

    def parse_adv_legacy(self, body: bytes) -> None:
        if not body:
            return
        num = body[0]
        off = 1
        for _ in range(num):
            try:
                addr = body[off + 2 : off + 8].hex(":")
                dlen = body[off + 8]
                self.scan_ad(body[off + 9 : off + 9 + dlen], addr)
                off += 9 + dlen
            except IndexError:
                return

    def parse_adv_extended(self, body: bytes) -> None:
        if not body:
            return
        num = body[0]
        off = 1
        for _ in range(num):
            try:
                addr = body[off + 3 : off + 9].hex(":")
                dlen = body[off + 9]
                self.scan_ad(body[off + 10 : off + 10 + dlen], addr)
                off += 10 + dlen + 1
            except IndexError:
                return

    def scan_ad(self, data: bytes, addr: str) -> None:
        info = self.adv.setdefault(addr, AdvInfo())
        i = 0
        while i < len(data):
            ln = data[i]
            if ln == 0 or i + 1 + ln > len(data):
                break
            typ = data[i + 1]
            seg = data[i + 2 : i + 1 + ln]
            if typ in AD_TYPES_NAMES:
                name = seg.decode("utf-8", "replace").strip()
                if name:
                    info.names.add(name)
            elif typ in AD_TYPES_UUID16:
                for j in range(0, len(seg) - 1, 2):
                    info.uuids.add(fmt_uuid(seg[j : j + 2]))
            elif typ in AD_TYPES_UUID128:
                for j in range(0, len(seg) - 15, 16):
                    info.uuids.add(fmt_uuid(seg[j : j + 16]))
            i += ln + 1


def analyze(path: str | Path) -> Analyzer:
    an = Analyzer()
    for rec in read_btsnoop(path):
        an.feed(rec)
    return an


def fmt_time(ts: int) -> str:
    if ts > 10**17:
        ts -= TS_0AD_TO_1970_US
    try:
        return datetime.fromtimestamp(ts / 1_000_000, tz=timezone.utc).strftime("%H:%M:%S.%f")[:-3]
    except (OverflowError, OSError, ValueError):
        return str(ts)


def battery_of(f: OneMoreFrame) -> tuple[int, int, int] | None:
    """(left%, right%, case%) из ответа 0x4E, либо None."""
    p = f.payload
    if f.cmd != CMD_BT_STATUS or f.direction_byte != 0x01 or len(p) < 10:
        return None
    return p[4], p[8], p[9]


def decode_value(f: OneMoreFrame) -> str:
    p = f.payload
    if not p:
        return ""
    if f.cmd in (CMD_ANC_SET, CMD_ANC_GET) and len(p) == 1:
        return f" ({ANC_MODES.get(p[0], f'режим {p[0]}?')})"
    if f.cmd in (CMD_LINK_SET, CMD_LINK_GET) and len(p) == 1:
        return f" ({LINK_MODES.get(p[0], f'режим {p[0]}?')})"
    if f.cmd in (CMD_EQ_SET, CMD_EQ_GET) and len(p) == 1:
        return f" (пресет {p[0]})"
    battery = battery_of(f)
    if battery:
        left, right, case = battery
        return f" (L={left}% R={right}% кейс={case}%)"
    return ""


def describe_frame(f: OneMoreFrame) -> str:
    name = CMD_NAMES.get(f.cmd, "неизвестная")
    cs = {True: "OK", False: "BAD", None: "?"}[f.checksum_ok]
    arrow = "host->buds" if f.direction_byte == 0x11 else "buds->host"
    return (
        f"cmd=0x{f.cmd:02X} ({name}) {arrow} len={f.length} seq={f.seq} "
        f"crc={cs} variant={f.variant} payload={f.payload.hex()}{decode_value(f)}"
    )


def render_report(an: Analyzer, label: str, raw: bool = False) -> str:
    lines = [f"# Отчёт btsnoop: {label}", ""]
    total_frames = sum(an.cmd_stats.values())
    lines.append(
        f"- записей HCI: ACL={an.acl_count}, EVT={an.evt_count}, SDP={an.sdp_count}, "
        f"пропущено ACL-продолжений={an.skipped_fragments}"
    )
    lines.append(
        f"- ATT/RFCOMM событий: {len(an.events)}, кадров 1MORE: {total_frames}, "
        f"с плохой чексуммой: {an.checksum_bad}"
    )
    if an.adv:
        lines += ["", "## BLE-устройства в эфире"]
        for addr, info in sorted(an.adv.items()):
            names = ", ".join(sorted(info.names)) or "?"
            uuids = ", ".join(sorted(info.uuids)) or "-"
            lines.append(f"- {addr}: {names} [{uuids}]")
    if an.gatt.services or an.gatt.chars:
        lines += ["", "## GATT"]
        for start, end, uuid in an.gatt.services:
            lines.append(f"- сервис {uuid} (handles 0x{start:04X}-0x{end:04X})")
        for handle in sorted(an.gatt.chars):
            lines.append(f"- характеристика 0x{handle:04X} -> {an.gatt.chars[handle]}")
    if an.cmd_stats:
        lines += ["", "## Команды 1MORE", "", "| cmd | имя | TX | RX |", "|---|---|---|---|"]
        for c in sorted({cmd for _, cmd in an.cmd_stats}):
            name = CMD_NAMES.get(c, "неизвестная")
            tx = an.cmd_stats.get(("TX", c), 0)
            rx = an.cmd_stats.get(("RX", c), 0)
            lines.append(f"| 0x{c:02X} | {name} | {tx} | {rx} |")
    shown = an.events if raw else [e for e in an.events if e.frames]
    if shown:
        lines += ["", "## Все payload" if raw else "## Кадры 1MORE"]
        for e in shown:
            suffix = ""
            if e.handle is not None:
                cu = an.gatt.uuid(e.handle)
                suffix = f" -> {cu}" if cu else f" h=0x{e.handle:04X}"
            lines.append(f"- {fmt_time(e.ts)} {e.direction} {e.transport}{suffix}")
            if e.frames:
                for f in e.frames:
                    lines.append(f"  - {describe_frame(f)}")
            else:
                lines.append(f"  - payload: {e.payload.hex()}")
    if not an.cmd_stats:
        lines += [
            "",
            "Кадров 1MORE не найдено. Проверьте, что лог снят во время активной сессии",
            "официального приложения (подключение наушников + действия в интерфейсе).",
        ]
    return "\n".join(lines) + "\n"


def analyze_file(path: str | Path, raw: bool = False, out: str | Path | None = None) -> None:
    report = render_report(analyze(path), str(path), raw)
    if out:
        Path(out).write_text(report, encoding="utf-8")
        print(f"Отчёт: {out}")
    else:
        print(report, end="")


def main() -> None:
    ap = argparse.ArgumentParser(description="Извлекает кадры протокола 1MORE из btsnoop_hci.log")
    ap.add_argument("files", nargs="+", help="файлы btsnoop_hci.log")
    ap.add_argument("-o", "--out", help="файл отчёта (только для одного входного файла)")
    ap.add_argument("--raw", action="store_true", help="показывать все ATT/RFCOMM payload, не только кадры 1MORE")
    args = ap.parse_args()
    if args.out and len(args.files) > 1:
        ap.error("-o/--out можно использовать только с одним входным файлом")
    failed = False
    for f in args.files:
        try:
            analyze_file(f, args.raw, args.out)
        except (OSError, ValueError) as e:
            print(f"Ошибка: {e}", file=sys.stderr)
            failed = True
    if failed:
        sys.exit(1)


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""Парсер btsnoop_hci.log: извлекает ATT (BLE GATT) и RFCOMM (SPP) payload и ищет кадры протокола 1MORE/JieLi.

Использование:
    python3 tools/btsnoop.py captures/btsnoop_hci.log -o captures/report.md   # -o — только с одним файлом
    python3 tools/btsnoop.py captures/*.log --raw                              # отчёты в stdout

Только stdlib, Python 3.10+. Тесты: python3 tests/test_btsnoop.py
"""

import argparse
import operator
import struct
import sys
from collections import Counter
from dataclasses import dataclass, field
from datetime import datetime, timezone
from functools import reduce
from pathlib import Path

MAGIC = b"btsnoop\0"
DLT_H4 = 1002

H4_ACL = 0x02
H4_EVT = 0x04

EVT_LE_META = 0x3E
LE_ADV_LEGACY = 0x01
LE_ADV_EXTENDED = 0x02

L2CAP_SDP = 0x0001
L2CAP_ATT = 0x0004
L2CAP_RFCOMM_MIN = 0x0040

ATT_READ_BY_TYPE_RESP = 0x09
ATT_WRITE_REQ = 0x12
ATT_READ_BY_GROUP_RESP = 0x11
ATT_NOTIFY = 0x1B
ATT_INDICATE = 0x1D
ATT_WRITE_CMD = 0x52

RFCOMM_CONTROLS = {0x0F, 0x1F, 0x2F, 0x3F, 0x43, 0x53, 0x63, 0x73, 0xEF, 0xFF}

AD_TYPES_NAMES = {0x08, 0x09}
AD_TYPES_UUID16 = {0x02, 0x03}
AD_TYPES_UUID128 = {0x06, 0x07}

FRAME_DIR = (0x11, 0x01)
FRAME_PREFIX = (0x01, 0x00)
FRAME_MIN_LEN = 9
FRAME_MAX_PAYLOAD = 512

UUID16_BASE = "0000-1000-8000-00805f9b34fb"

CMD_DEVICE_INFO = 0x36
CMD_BATTERY_INFO = 0x37
CMD_DELETE_MUSIC = 0x49
CMD_HANDSHAKE = 0x4D
CMD_BT_STATUS = 0x4E
CMD_EQ_SET_BAND = 0x53
CMD_EQ_BANDS = 0x54
CMD_ANC_SET = 0x5E
CMD_ANC_GET = 0x5F
CMD_AWARENESS_SET = 0x60
CMD_AWARENESS_GET = 0x61
CMD_EQ_SET = 0x69
CMD_EQ_GET = 0x6A
CMD_LINK_SET = 0x6B
CMD_LINK_GET = 0x6C
CMD_FW_UPDATE = (0x71, 0x72, 0x73)

CMD_NAMES = {
    CMD_DEVICE_INFO: "query device info",
    CMD_BATTERY_INFO: "query battery info",
    CMD_DELETE_MUSIC: "DELETE MUSIC (никогда не слать)",
    CMD_HANDSHAKE: "handshake",
    CMD_BT_STATUS: "battery / bt status",
    CMD_EQ_SET_BAND: "set EQ band",
    CMD_EQ_BANDS: "EQ band table",
    CMD_ANC_SET: "set listening mode (ANC)",
    CMD_ANC_GET: "get listening mode (ANC)",
    CMD_AWARENESS_SET: "set total awareness",
    CMD_AWARENESS_GET: "get total awareness",
    CMD_EQ_SET: "set sound preset (EQ)",
    CMD_EQ_GET: "get sound preset (EQ)",
    CMD_LINK_SET: "set game/link mode",
    CMD_LINK_GET: "get game/link mode",
    **dict.fromkeys(CMD_FW_UPDATE, "FW UPDATE (опасно)"),
}

ANC_MODES = {
    0: "выкл",
    1: "сильный ANC",
    2: "слабый ANC",
    3: "прозрачность",
    4: "анти-ветер",
    5: "пропускание голоса",
    6: "усиление голоса",
    7: "адаптивный",
}

LINK_MODES = {0: "стандарт", 1: "низкая задержка", 2: "LDAC"}

TS_0AD_TO_1970_US = 62135596800000000


def xor(data: bytes) -> int:
    return reduce(operator.xor, data, 0)



@dataclass
class OneMoreFrame:
    direction_byte: int
    cmd: int
    length: int
    seq: int
    checksum_byte: int
    checksum_ok: bool | None
    variant: str
    payload: bytes

    @property
    def total_len(self) -> int:
        return 9 + self.length


def parse_onemore(data: bytes) -> OneMoreFrame | None:
    if len(data) < FRAME_MIN_LEN:
        return None
    if data[0] not in FRAME_DIR or tuple(data[1:3]) != FRAME_PREFIX:
        return None
    if (data[6], data[7]) == (0x00, 0x01):
        variant = "BE"
        length = struct.unpack(">H", data[4:6])[0]
        seq = struct.unpack(">H", data[6:8])[0]
        checksum_ok = xor(data[:8]) == data[8]
    elif (data[6], data[7]) == (0x01, 0x00):
        variant = "LE"
        length = struct.unpack("<H", data[4:6])[0]
        seq = struct.unpack("<H", data[6:8])[0]
        checksum_ok = None
    else:
        return None
    if length > FRAME_MAX_PAYLOAD:
        return None
    return OneMoreFrame(data[0], data[3], length, seq, data[8], checksum_ok, variant, data[9 : 9 + length])


def extract_onemore(data: bytes) -> list[tuple[int, OneMoreFrame]]:
    found = []
    pos = 0
    while pos + FRAME_MIN_LEN <= len(data):
        frame = parse_onemore(data[pos:])
        if frame is None:
            pos += 1
            continue
        found.append((pos, frame))
        pos += frame.total_len
    return found


def fmt_uuid(raw: bytes) -> str:
    if len(raw) == 2:
        return f"0x{raw.hex()}"
    if len(raw) == 16:
        s = raw[::-1].hex()
        u = f"{s[:8]}-{s[8:12]}-{s[12:16]}-{s[16:20]}-{s[20:]}"
        if u[9:] == UUID16_BASE:
            return f"0x{u[:4]}"
        return u
    return raw.hex()


@dataclass(slots=True)
class GattMap:
    services: list[tuple[int, int, str]] = field(default_factory=list)
    chars: dict[int, str] = field(default_factory=dict)

    def add_service(self, start: int, end: int, uuid: str) -> None:
        self.services.append((start, end, uuid))

    def add_char_decl(self, value: int, uuid: str) -> None:
        self.chars[value] = uuid

    def uuid(self, handle: int) -> str:
        return self.chars.get(handle, "")


@dataclass(slots=True)
class AdvInfo:
    names: set[str] = field(default_factory=set)
    uuids: set[str] = field(default_factory=set)


@dataclass(slots=True)
class Record:
    ts: int
    tx: bool
    data: bytes


@dataclass(slots=True)
class Event:
    ts: int
    direction: str
    transport: str
    handle: int | None
    payload: bytes
    frames: list[OneMoreFrame] = field(default_factory=list)


def read_btsnoop(path: str | Path):
    blob = Path(path).read_bytes()
    if blob[:8] != MAGIC:
        raise ValueError(f"{path}: нет сигнатуры btsnoop")
    pos = 16
    while pos + 24 <= len(blob):
        _orig, inc, flags, _drops = struct.unpack(">IIII", blob[pos : pos + 16])
        (ts,) = struct.unpack(">q", blob[pos + 16 : pos + 24])
        pos += 24
        data = blob[pos : pos + inc]
        pos += inc
        yield Record(ts, (flags & 1) == 0, data)


class Analyzer:
    def __init__(self) -> None:
        self.gatt = GattMap()
        self.events: list[Event] = []
        self.adv: dict[str, AdvInfo] = {}
        self.cmd_stats: Counter = Counter()
        self.acl_count = 0
        self.evt_count = 0
        self.sdp_count = 0
        self.skipped_fragments = 0
        self.checksum_bad = 0

    def feed(self, rec: Record) -> None:
        data = rec.data
        if not data:
            return
        if data[0] == H4_ACL:
            self.acl_count += 1
            self.parse_acl(rec, data[1:])
        elif data[0] == H4_EVT:
            self.evt_count += 1
            self.parse_evt(data[1:])

    def parse_acl(self, rec: Record, p: bytes) -> None:
        if len(p) < 5:
            return
        hb, dlen = struct.unpack("<HH", p[:4])
        if ((hb >> 12) & 0b11) == 0b01:
            self.skipped_fragments += 1
            return
        l2 = p[4 : 4 + dlen]
        if len(l2) < 4:
            return
        l2len, cid = struct.unpack("<HH", l2[:4])
        body = l2[4 : 4 + l2len]
        if cid == L2CAP_ATT:
            self.parse_att(rec, body)
        elif cid == L2CAP_SDP:
            self.sdp_count += 1
        elif cid >= L2CAP_RFCOMM_MIN:
            self.parse_rfcomm(rec, body)

    def parse_att(self, rec: Record, body: bytes) -> None:
        if not body:
            return
        op = body[0]
        if op in (ATT_WRITE_CMD, ATT_WRITE_REQ):
            if len(body) >= 3:
                (handle,) = struct.unpack("<H", body[1:3])
                self.emit(rec, "ATT write", handle, body[3:])
        elif op in (ATT_NOTIFY, ATT_INDICATE):
            if len(body) >= 3:
                (handle,) = struct.unpack("<H", body[1:3])
                self.emit(rec, "ATT notify" if op == ATT_NOTIFY else "ATT indicate", handle, body[3:])
        elif op == ATT_READ_BY_GROUP_RESP:
            self.parse_services(body[1:])
        elif op == ATT_READ_BY_TYPE_RESP:
            self.parse_char_decls(body[1:])

    def parse_services(self, entries: bytes) -> None:
        for size in (20, 6):
            if entries and len(entries) % size == 0:
                for off in range(0, len(entries), size):
                    start, end = struct.unpack("<HH", entries[off : off + 4])
                    self.gatt.add_service(start, end, fmt_uuid(entries[off + 4 : off + size]))
                break

    def parse_char_decls(self, entries: bytes) -> None:
        for size in (21, 7):
            if entries and len(entries) % size == 0:
                for off in range(0, len(entries), size):
                    _decl, _props, value = struct.unpack("<HBH", entries[off : off + 5])
                    self.gatt.add_char_decl(value, fmt_uuid(entries[off + 5 : off + size]))
                break

    def parse_rfcomm(self, rec: Record, payload: bytes) -> None:
        if len(payload) < 4 or payload[0] & 1 == 0:
            return
        control = payload[1]
        if control not in RFCOMM_CONTROLS:
            return
        if payload[2] & 1:
            length = payload[2] >> 1
            dstart = 3
        else:
            if len(payload) < 5:
                return
            length = struct.unpack("<H", payload[2:4])[0] >> 1
            dstart = 4
        data = payload[dstart : dstart + length]
        self.emit(rec, "RFCOMM", None, data)

    def emit(self, rec: Record, transport: str, handle: int | None, value: bytes) -> None:
        frames = [f for _, f in extract_onemore(value)]
        direction = "TX" if rec.tx else "RX"
        for f in frames:
            self.cmd_stats[(direction, f.cmd)] += 1
            if f.checksum_ok is False:
                self.checksum_bad += 1
        self.events.append(Event(rec.ts, direction, transport, handle, value, frames))

    def parse_evt(self, p: bytes) -> None:
        if len(p) < 2:
            return
        code, plen = p[0], p[1]
        if code != EVT_LE_META:
            return
        body = p[2 : 2 + plen]
        if not body:
            return
        sub = body[0]
        if sub == LE_ADV_LEGACY:
            self.parse_adv_legacy(body[1:])
        elif sub == LE_ADV_EXTENDED:
            self.parse_adv_extended(body[1:])

    def parse_adv_legacy(self, body: bytes) -> None:
        if not body:
            return
        num = body[0]
        off = 1
        for _ in range(num):
            try:
                addr = body[off + 2 : off + 8].hex(":")
                dlen = body[off + 8]
                self.scan_ad(body[off + 9 : off + 9 + dlen], addr)
                off += 9 + dlen
            except IndexError:
                return

    def parse_adv_extended(self, body: bytes) -> None:
        if not body:
            return
        num = body[0]
        off = 1
        for _ in range(num):
            try:
                addr = body[off + 3 : off + 9].hex(":")
                dlen = body[off + 9]
                self.scan_ad(body[off + 10 : off + 10 + dlen], addr)
                off += 10 + dlen + 1
            except IndexError:
                return

    def scan_ad(self, data: bytes, addr: str) -> None:
        info = self.adv.setdefault(addr, AdvInfo())
        i = 0
        while i < len(data):
            ln = data[i]
            if ln == 0 or i + 1 + ln > len(data):
                break
            typ = data[i + 1]
            seg = data[i + 2 : i + 1 + ln]
            if typ in AD_TYPES_NAMES:
                name = seg.decode("utf-8", "replace").strip()
                if name:
                    info.names.add(name)
            elif typ in AD_TYPES_UUID16:
                for j in range(0, len(seg) - 1, 2):
                    info.uuids.add(fmt_uuid(seg[j : j + 2]))
            elif typ in AD_TYPES_UUID128:
                for j in range(0, len(seg) - 15, 16):
                    info.uuids.add(fmt_uuid(seg[j : j + 16]))
            i += ln + 1


def analyze(path: str | Path) -> Analyzer:
    an = Analyzer()
    for rec in read_btsnoop(path):
        an.feed(rec)
    return an


def fmt_time(ts: int) -> str:
    if ts > 10**17:
        ts -= TS_0AD_TO_1970_US
    try:
        return datetime.fromtimestamp(ts / 1_000_000, tz=timezone.utc).strftime("%H:%M:%S.%f")[:-3]
    except (OverflowError, OSError, ValueError):
        return str(ts)


def battery_of(f: OneMoreFrame) -> tuple[int, int, int] | None:
    """(left%, right%, case%) из ответа 0x4E, либо None."""
    p = f.payload
    if f.cmd != CMD_BT_STATUS or f.direction_byte != 0x01 or len(p) < 10:
        return None
    return p[4], p[8], p[9]


def decode_value(f: OneMoreFrame) -> str:
    p = f.payload
    if not p:
        return ""
    if f.cmd in (CMD_ANC_SET, CMD_ANC_GET) and len(p) == 1:
        return f" ({ANC_MODES.get(p[0], f'режим {p[0]}?')})"
    if f.cmd in (CMD_LINK_SET, CMD_LINK_GET) and len(p) == 1:
        return f" ({LINK_MODES.get(p[0], f'режим {p[0]}?')})"
    if f.cmd in (CMD_EQ_SET, CMD_EQ_GET) and len(p) == 1:
        return f" (пресет {p[0]})"
    battery = battery_of(f)
    if battery:
        left, right, case = battery
        return f" (L={left}% R={right}% кейс={case}%)"
    return ""


def describe_frame(f: OneMoreFrame) -> str:
    name = CMD_NAMES.get(f.cmd, "неизвестная")
    cs = {True: "OK", False: "BAD", None: "?"}[f.checksum_ok]
    arrow = "host->buds" if f.direction_byte == 0x11 else "buds->host"
    return (
        f"cmd=0x{f.cmd:02X} ({name}) {arrow} len={f.length} seq={f.seq} "
        f"crc={cs} variant={f.variant} payload={f.payload.hex()}{decode_value(f)}"
    )


def render_report(an: Analyzer, label: str, raw: bool = False) -> str:
    lines = [f"# Отчёт btsnoop: {label}", ""]
    total_frames = sum(an.cmd_stats.values())
    lines.append(
        f"- записей HCI: ACL={an.acl_count}, EVT={an.evt_count}, SDP={an.sdp_count}, "
        f"пропущено ACL-продолжений={an.skipped_fragments}"
    )
    lines.append(
        f"- ATT/RFCOMM событий: {len(an.events)}, кадров 1MORE: {total_frames}, "
        f"с плохой чексуммой: {an.checksum_bad}"
    )
    if an.adv:
        lines += ["", "## BLE-устройства в эфире"]
        for addr, info in sorted(an.adv.items()):
            names = ", ".join(sorted(info.names)) or "?"
            uuids = ", ".join(sorted(info.uuids)) or "-"
            lines.append(f"- {addr}: {names} [{uuids}]")
    if an.gatt.services or an.gatt.chars:
        lines += ["", "## GATT"]
        for start, end, uuid in an.gatt.services:
            lines.append(f"- сервис {uuid} (handles 0x{start:04X}-0x{end:04X})")
        for handle in sorted(an.gatt.chars):
            lines.append(f"- характеристика 0x{handle:04X} -> {an.gatt.chars[handle]}")
    if an.cmd_stats:
        lines += ["", "## Команды 1MORE", "", "| cmd | имя | TX | RX |", "|---|---|---|---|"]
        for c in sorted({cmd for _, cmd in an.cmd_stats}):
            name = CMD_NAMES.get(c, "неизвестная")
            tx = an.cmd_stats.get(("TX", c), 0)
            rx = an.cmd_stats.get(("RX", c), 0)
            lines.append(f"| 0x{c:02X} | {name} | {tx} | {rx} |")
    shown = an.events if raw else [e for e in an.events if e.frames]
    if shown:
        lines += ["", "## Все payload" if raw else "## Кадры 1MORE"]
        for e in shown:
            suffix = ""
            if e.handle is not None:
                cu = an.gatt.uuid(e.handle)
                suffix = f" -> {cu}" if cu else f" h=0x{e.handle:04X}"
            lines.append(f"- {fmt_time(e.ts)} {e.direction} {e.transport}{suffix}")
            if e.frames:
                for f in e.frames:
                    lines.append(f"  - {describe_frame(f)}")
            else:
                lines.append(f"  - payload: {e.payload.hex()}")
    if not an.cmd_stats:
        lines += [
            "",
            "Кадров 1MORE не найдено. Проверьте, что лог снят во время активной сессии",
            "официального приложения (подключение наушников + действия в интерфейсе).",
        ]
    return "\n".join(lines) + "\n"


def analyze_file(path: str | Path, raw: bool = False, out: str | Path | None = None) -> None:
    report = render_report(analyze(path), str(path), raw)
    if out:
        Path(out).write_text(report, encoding="utf-8")
        print(f"Отчёт: {out}")
    else:
        print(report, end="")


def main() -> None:
    ap = argparse.ArgumentParser(description="Извлекает кадры протокола 1MORE из btsnoop_hci.log")
    ap.add_argument("files", nargs="+", help="файлы btsnoop_hci.log")
    ap.add_argument("-o", "--out", help="файл отчёта (только для одного входного файла)")
    ap.add_argument("--raw", action="store_true", help="показывать все ATT/RFCOMM payload, не только кадры 1MORE")
    args = ap.parse_args()
    if args.out and len(args.files) > 1:
        ap.error("-o/--out можно использовать только с одним входным файлом")
    failed = False
    for f in args.files:
        try:
            analyze_file(f, args.raw, args.out)
        except (OSError, ValueError) as e:
            print(f"Ошибка: {e}", file=sys.stderr)
            failed = True
    if failed:
        sys.exit(1)


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""Парсер btsnoop_hci.log: извлекает ATT (BLE GATT) и RFCOMM (SPP) payload и ищет кадры протокола 1MORE/JieLi.

Использование:
    python3 tools/btsnoop.py captures/btsnoop_hci.log -o captures/report.md   # -o — только с одним файлом
    python3 tools/btsnoop.py captures/*.log --raw                              # отчёты в stdout

Только stdlib, Python 3.10+. Тесты: python3 tests/test_btsnoop.py
"""

import argparse
import operator
import struct
import sys
from collections import Counter
from dataclasses import dataclass, field
from datetime import datetime, timezone
from functools import reduce
from pathlib import Path

MAGIC = b"btsnoop\0"
DLT_H4 = 1002

H4_ACL = 0x02
H4_EVT = 0x04

EVT_LE_META = 0x3E
LE_ADV_LEGACY = 0x01
LE_ADV_EXTENDED = 0x02

L2CAP_SDP = 0x0001
L2CAP_ATT = 0x0004
L2CAP_RFCOMM_MIN = 0x0040

ATT_READ_BY_TYPE_RESP = 0x09
ATT_WRITE_REQ = 0x12
ATT_READ_BY_GROUP_RESP = 0x11
ATT_NOTIFY = 0x1B
ATT_INDICATE = 0x1D
ATT_WRITE_CMD = 0x52

RFCOMM_CONTROLS = {0x0F, 0x1F, 0x2F, 0x3F, 0x43, 0x53, 0x63, 0x73, 0xEF, 0xFF}

AD_TYPES_NAMES = {0x08, 0x09}
AD_TYPES_UUID16 = {0x02, 0x03}
AD_TYPES_UUID128 = {0x06, 0x07}

FRAME_DIR = (0x11, 0x01)
FRAME_PREFIX = (0x01, 0x00)
FRAME_MIN_LEN = 9
FRAME_MAX_PAYLOAD = 512

UUID16_BASE = "0000-1000-8000-00805f9b34fb"

CMD_DEVICE_INFO = 0x36
CMD_BATTERY_INFO = 0x37
CMD_DELETE_MUSIC = 0x49
CMD_HANDSHAKE = 0x4D
CMD_BT_STATUS = 0x4E
CMD_EQ_SET_BAND = 0x53
CMD_EQ_BANDS = 0x54
CMD_ANC_SET = 0x5E
CMD_ANC_GET = 0x5F
CMD_AWARENESS_SET = 0x60
CMD_AWARENESS_GET = 0x61
CMD_EQ_SET = 0x69
CMD_EQ_GET = 0x6A
CMD_LINK_SET = 0x6B
CMD_LINK_GET = 0x6C
CMD_FW_UPDATE = (0x71, 0x72, 0x73)

CMD_NAMES = {
    CMD_DEVICE_INFO: "query device info",
    CMD_BATTERY_INFO: "query battery info",
    CMD_DELETE_MUSIC: "DELETE MUSIC (никогда не слать)",
    CMD_HANDSHAKE: "handshake",
    CMD_BT_STATUS: "battery / bt status",
    CMD_EQ_SET_BAND: "set EQ band",
    CMD_EQ_BANDS: "EQ band table",
    CMD_ANC_SET: "set listening mode (ANC)",
    CMD_ANC_GET: "get listening mode (ANC)",
    CMD_AWARENESS_SET: "set total awareness",
    CMD_AWARENESS_GET: "get total awareness",
    CMD_EQ_SET: "set sound preset (EQ)",
    CMD_EQ_GET: "get sound preset (EQ)",
    CMD_LINK_SET: "set game/link mode",
    CMD_LINK_GET: "get game/link mode",
    **dict.fromkeys(CMD_FW_UPDATE, "FW UPDATE (опасно)"),
}

ANC_MODES = {
    0: "выкл",
    1: "сильный ANC",
    2: "слабый ANC",
    3: "прозрачность",
    4: "анти-ветер",
    5: "пропускание голоса",
    6: "усиление голоса",
    7: "адаптивный",
}

LINK_MODES = {0: "стандарт", 1: "низкая задержка", 2: "LDAC"}

TS_0AD_TO_1970_US = 62135596800000000


def xor(data: bytes) -> int:
    return reduce(operator.xor, data, 0)



@dataclass
class OneMoreFrame:
    direction_byte: int
    cmd: int
    length: int
    seq: int
    checksum_byte: int
    checksum_ok: bool | None
    variant: str
    payload: bytes

    @property
    def total_len(self) -> int:
        return 9 + self.length


def parse_onemore(data: bytes) -> OneMoreFrame | None:
    if len(data) < FRAME_MIN_LEN:
        return None
    if data[0] not in FRAME_DIR or tuple(data[1:3]) != FRAME_PREFIX:
        return None
    if (data[6], data[7]) == (0x00, 0x01):
        variant = "BE"
        length = struct.unpack(">H", data[4:6])[0]
        seq = struct.unpack(">H", data[6:8])[0]
        checksum_ok = xor(data[:8]) == data[8]
    elif (data[6], data[7]) == (0x01, 0x00):
        variant = "LE"
        length = struct.unpack("<H", data[4:6])[0]
        seq = struct.unpack("<H", data[6:8])[0]
        checksum_ok = None
    else:
        return None
    if length > FRAME_MAX_PAYLOAD:
        return None
    return OneMoreFrame(data[0], data[3], length, seq, data[8], checksum_ok, variant, data[9 : 9 + length])


def extract_onemore(data: bytes) -> list[tuple[int, OneMoreFrame]]:
    found = []
    pos = 0
    while pos + FRAME_MIN_LEN <= len(data):
        frame = parse_onemore(data[pos:])
        if frame is None:
            pos += 1
            continue
        found.append((pos, frame))
        pos += frame.total_len
    return found


def fmt_uuid(raw: bytes) -> str:
    if len(raw) == 2:
        return f"0x{raw.hex()}"
    if len(raw) == 16:
        s = raw[::-1].hex()
        u = f"{s[:8]}-{s[8:12]}-{s[12:16]}-{s[16:20]}-{s[20:]}"
        if u[9:] == UUID16_BASE:
            return f"0x{u[:4]}"
        return u
    return raw.hex()


@dataclass(slots=True)
class GattMap:
    services: list[tuple[int, int, str]] = field(default_factory=list)
    chars: dict[int, str] = field(default_factory=dict)

    def add_service(self, start: int, end: int, uuid: str) -> None:
        self.services.append((start, end, uuid))

    def add_char_decl(self, value: int, uuid: str) -> None:
        self.chars[value] = uuid

    def uuid(self, handle: int) -> str:
        return self.chars.get(handle, "")


@dataclass(slots=True)
class AdvInfo:
    names: set[str] = field(default_factory=set)
    uuids: set[str] = field(default_factory=set)


@dataclass(slots=True)
class Record:
    ts: int
    tx: bool
    data: bytes


@dataclass(slots=True)
class Event:
    ts: int
    direction: str
    transport: str
    handle: int | None
    payload: bytes
    frames: list[OneMoreFrame] = field(default_factory=list)


def read_btsnoop(path: str | Path):
    blob = Path(path).read_bytes()
    if blob[:8] != MAGIC:
        raise ValueError(f"{path}: нет сигнатуры btsnoop")
    pos = 16
    while pos + 24 <= len(blob):
        _orig, inc, flags, _drops = struct.unpack(">IIII", blob[pos : pos + 16])
        (ts,) = struct.unpack(">q", blob[pos + 16 : pos + 24])
        pos += 24
        data = blob[pos : pos + inc]
        pos += inc
        yield Record(ts, (flags & 1) == 0, data)


class Analyzer:
    def __init__(self) -> None:
        self.gatt = GattMap()
        self.events: list[Event] = []
        self.adv: dict[str, AdvInfo] = {}
        self.cmd_stats: Counter = Counter()
        self.acl_count = 0
        self.evt_count = 0
        self.sdp_count = 0
        self.skipped_fragments = 0
        self.checksum_bad = 0

    def feed(self, rec: Record) -> None:
        data = rec.data
        if not data:
            return
        if data[0] == H4_ACL:
            self.acl_count += 1
            self.parse_acl(rec, data[1:])
        elif data[0] == H4_EVT:
            self.evt_count += 1
            self.parse_evt(data[1:])

    def parse_acl(self, rec: Record, p: bytes) -> None:
        if len(p) < 5:
            return
        hb, dlen = struct.unpack("<HH", p[:4])
        if ((hb >> 12) & 0b11) == 0b01:
            self.skipped_fragments += 1
            return
        l2 = p[4 : 4 + dlen]
        if len(l2) < 4:
            return
        l2len, cid = struct.unpack("<HH", l2[:4])
        body = l2[4 : 4 + l2len]
        if cid == L2CAP_ATT:
            self.parse_att(rec, body)
        elif cid == L2CAP_SDP:
            self.sdp_count += 1
        elif cid >= L2CAP_RFCOMM_MIN:
            self.parse_rfcomm(rec, body)

    def parse_att(self, rec: Record, body: bytes) -> None:
        if not body:
            return
        op = body[0]
        if op in (ATT_WRITE_CMD, ATT_WRITE_REQ):
            if len(body) >= 3:
                (handle,) = struct.unpack("<H", body[1:3])
                self.emit(rec, "ATT write", handle, body[3:])
        elif op in (ATT_NOTIFY, ATT_INDICATE):
            if len(body) >= 3:
                (handle,) = struct.unpack("<H", body[1:3])
                self.emit(rec, "ATT notify" if op == ATT_NOTIFY else "ATT indicate", handle, body[3:])
        elif op == ATT_READ_BY_GROUP_RESP:
            self.parse_services(body[1:])
        elif op == ATT_READ_BY_TYPE_RESP:
            self.parse_char_decls(body[1:])

    def parse_services(self, entries: bytes) -> None:
        for size in (20, 6):
            if entries and len(entries) % size == 0:
                for off in range(0, len(entries), size):
                    start, end = struct.unpack("<HH", entries[off : off + 4])
                    self.gatt.add_service(start, end, fmt_uuid(entries[off + 4 : off + size]))
                break

    def parse_char_decls(self, entries: bytes) -> None:
        for size in (21, 7):
            if entries and len(entries) % size == 0:
                for off in range(0, len(entries), size):
                    _decl, _props, value = struct.unpack("<HBH", entries[off : off + 5])
                    self.gatt.add_char_decl(value, fmt_uuid(entries[off + 5 : off + size]))
                break

    def parse_rfcomm(self, rec: Record, payload: bytes) -> None:
        if len(payload) < 4 or payload[0] & 1 == 0:
            return
        control = payload[1]
        if control not in RFCOMM_CONTROLS:
            return
        if payload[2] & 1:
            length = payload[2] >> 1
            dstart = 3
        else:
            if len(payload) < 5:
                return
            length = struct.unpack("<H", payload[2:4])[0] >> 1
            dstart = 4
        data = payload[dstart : dstart + length]
        self.emit(rec, "RFCOMM", None, data)

    def emit(self, rec: Record, transport: str, handle: int | None, value: bytes) -> None:
        frames = [f for _, f in extract_onemore(value)]
        direction = "TX" if rec.tx else "RX"
        for f in frames:
            self.cmd_stats[(direction, f.cmd)] += 1
            if f.checksum_ok is False:
                self.checksum_bad += 1
        self.events.append(Event(rec.ts, direction, transport, handle, value, frames))

    def parse_evt(self, p: bytes) -> None:
        if len(p) < 2:
            return
        code, plen = p[0], p[1]
        if code != EVT_LE_META:
            return
        body = p[2 : 2 + plen]
        if not body:
            return
        sub = body[0]
        if sub == LE_ADV_LEGACY:
            self.parse_adv_legacy(body[1:])
        elif sub == LE_ADV_EXTENDED:
            self.parse_adv_extended(body[1:])

    def parse_adv_legacy(self, body: bytes) -> None:
        if not body:
            return
        num = body[0]
        off = 1
        for _ in range(num):
            try:
                addr = body[off + 2 : off + 8].hex(":")
                dlen = body[off + 8]
                self.scan_ad(body[off + 9 : off + 9 + dlen], addr)
                off += 9 + dlen
            except IndexError:
                return

    def parse_adv_extended(self, body: bytes) -> None:
        if not body:
            return
        num = body[0]
        off = 1
        for _ in range(num):
            try:
                addr = body[off + 3 : off + 9].hex(":")
                dlen = body[off + 9]
                self.scan_ad(body[off + 10 : off + 10 + dlen], addr)
                off += 10 + dlen + 1
            except IndexError:
                return

    def scan_ad(self, data: bytes, addr: str) -> None:
        info = self.adv.setdefault(addr, AdvInfo())
        i = 0
        while i < len(data):
            ln = data[i]
            if ln == 0 or i + 1 + ln > len(data):
                break
            typ = data[i + 1]
            seg = data[i + 2 : i + 1 + ln]
            if typ in AD_TYPES_NAMES:
                name = seg.decode("utf-8", "replace").strip()
                if name:
                    info.names.add(name)
            elif typ in AD_TYPES_UUID16:
                for j in range(0, len(seg) - 1, 2):
                    info.uuids.add(fmt_uuid(seg[j : j + 2]))
            elif typ in AD_TYPES_UUID128:
                for j in range(0, len(seg) - 15, 16):
                    info.uuids.add(fmt_uuid(seg[j : j + 16]))
            i += ln + 1


def analyze(path: str | Path) -> Analyzer:
    an = Analyzer()
    for rec in read_btsnoop(path):
        an.feed(rec)
    return an


def fmt_time(ts: int) -> str:
    if ts > 10**17:
        ts -= TS_0AD_TO_1970_US
    try:
        return datetime.fromtimestamp(ts / 1_000_000, tz=timezone.utc).strftime("%H:%M:%S.%f")[:-3]
    except (OverflowError, OSError, ValueError):
        return str(ts)


def battery_of(f: OneMoreFrame) -> tuple[int, int, int] | None:
    """(left%, right%, case%) из ответа 0x4E, либо None."""
    p = f.payload
    if f.cmd != CMD_BT_STATUS or f.direction_byte != 0x01 or len(p) < 10:
        return None
    return p[4], p[8], p[9]


def decode_value(f: OneMoreFrame) -> str:
    p = f.payload
    if not p:
        return ""
    if f.cmd in (CMD_ANC_SET, CMD_ANC_GET) and len(p) == 1:
        return f" ({ANC_MODES.get(p[0], f'режим {p[0]}?')})"
    if f.cmd in (CMD_LINK_SET, CMD_LINK_GET) and len(p) == 1:
        return f" ({LINK_MODES.get(p[0], f'режим {p[0]}?')})"
    if f.cmd in (CMD_EQ_SET, CMD_EQ_GET) and len(p) == 1:
        return f" (пресет {p[0]})"
    battery = battery_of(f)
    if battery:
        left, right, case = battery
        return f" (L={left}% R={right}% кейс={case}%)"
    return ""


def describe_frame(f: OneMoreFrame) -> str:
    name = CMD_NAMES.get(f.cmd, "неизвестная")
    cs = {True: "OK", False: "BAD", None: "?"}[f.checksum_ok]
    arrow = "host->buds" if f.direction_byte == 0x11 else "buds->host"
    return (
        f"cmd=0x{f.cmd:02X} ({name}) {arrow} len={f.length} seq={f.seq} "
        f"crc={cs} variant={f.variant} payload={f.payload.hex()}{decode_value(f)}"
    )


def render_report(an: Analyzer, label: str, raw: bool = False) -> str:
    lines = [f"# Отчёт btsnoop: {label}", ""]
    total_frames = sum(an.cmd_stats.values())
    lines.append(
        f"- записей HCI: ACL={an.acl_count}, EVT={an.evt_count}, SDP={an.sdp_count}, "
        f"пропущено ACL-продолжений={an.skipped_fragments}"
    )
    lines.append(
        f"- ATT/RFCOMM событий: {len(an.events)}, кадров 1MORE: {total_frames}, "
        f"с плохой чексуммой: {an.checksum_bad}"
    )
    if an.adv:
        lines += ["", "## BLE-устройства в эфире"]
        for addr, info in sorted(an.adv.items()):
            names = ", ".join(sorted(info.names)) or "?"
            uuids = ", ".join(sorted(info.uuids)) or "-"
            lines.append(f"- {addr}: {names} [{uuids}]")
    if an.gatt.services or an.gatt.chars:
        lines += ["", "## GATT"]
        for start, end, uuid in an.gatt.services:
            lines.append(f"- сервис {uuid} (handles 0x{start:04X}-0x{end:04X})")
        for handle in sorted(an.gatt.chars):
            lines.append(f"- характеристика 0x{handle:04X} -> {an.gatt.chars[handle]}")
    if an.cmd_stats:
        lines += ["", "## Команды 1MORE", "", "| cmd | имя | TX | RX |", "|---|---|---|---|"]
        for c in sorted({cmd for _, cmd in an.cmd_stats}):
            name = CMD_NAMES.get(c, "неизвестная")
            tx = an.cmd_stats.get(("TX", c), 0)
            rx = an.cmd_stats.get(("RX", c), 0)
            lines.append(f"| 0x{c:02X} | {name} | {tx} | {rx} |")
    shown = an.events if raw else [e for e in an.events if e.frames]
    if shown:
        lines += ["", "## Все payload" if raw else "## Кадры 1MORE"]
        for e in shown:
            suffix = ""
            if e.handle is not None:
                cu = an.gatt.uuid(e.handle)
                suffix = f" -> {cu}" if cu else f" h=0x{e.handle:04X}"
            lines.append(f"- {fmt_time(e.ts)} {e.direction} {e.transport}{suffix}")
            if e.frames:
                for f in e.frames:
                    lines.append(f"  - {describe_frame(f)}")
            else:
                lines.append(f"  - payload: {e.payload.hex()}")
    if not an.cmd_stats:
        lines += [
            "",
            "Кадров 1MORE не найдено. Проверьте, что лог снят во время активной сессии",
            "официального приложения (подключение наушников + действия в интерфейсе).",
        ]
    return "\n".join(lines) + "\n"


def analyze_file(path: str | Path, raw: bool = False, out: str | Path | None = None) -> None:
    report = render_report(analyze(path), str(path), raw)
    if out:
        Path(out).write_text(report, encoding="utf-8")
        print(f"Отчёт: {out}")
    else:
        print(report, end="")


def main() -> None:
    ap = argparse.ArgumentParser(description="Извлекает кадры протокола 1MORE из btsnoop_hci.log")
    ap.add_argument("files", nargs="+", help="файлы btsnoop_hci.log")
    ap.add_argument("-o", "--out", help="файл отчёта (только для одного входного файла)")
    ap.add_argument("--raw", action="store_true", help="показывать все ATT/RFCOMM payload, не только кадры 1MORE")
    args = ap.parse_args()
    if args.out and len(args.files) > 1:
        ap.error("-o/--out можно использовать только с одним входным файлом")
    failed = False
    for f in args.files:
        try:
            analyze_file(f, args.raw, args.out)
        except (OSError, ValueError) as e:
            print(f"Ошибка: {e}", file=sys.stderr)
            failed = True
    if failed:
        sys.exit(1)


if __name__ == "__main__":
    main()
